import argparse,json
from pathlib import Path
import numpy as np
from scipy.integrate import solve_ivp
ap=argparse.ArgumentParser();ap.add_argument('--output',required=True);a=ap.parse_args();dest=Path(a.output);k=.5;gamma=.005
# Exact normalized B sin^2(pi*x/2) potential from the candidate vacuum carrier.
def potential(s):return (1-np.cos(np.pi*(s-1)))/np.pi**2
def rhs(t,z):
 s,p,x,px,Q=z;return [p,-np.sin(np.pi*(s-1))/np.pi+px*px/s**3-s*k*k*x*x,px/s**2,-s*s*k*k*x-gamma*px,gamma*px*px/s**2]
